INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (10024, 'Viết văn bản thay thế cho dữ liệu trực quan (biểu đồ) trong SEO', 'viet-van-ban-thay-the-trong-du-lieu-truc-quan', '
<p>Bạn có thể không thể viết văn bản truyền đạt toàn bộ ý nghĩa của biểu đồ. Nhưng, điều đó không có nghĩa là bạn không nên thử.</p>



<h2 class="wp-block-heading" id="5bbd">Văn bản thay thế là gì?</h2>



<p id="4328">Văn bản thay thế&nbsp;(đôi khi được gọi là thẻ Alt) là các mô tả bằng văn bản được thêm vào hình ảnh để truyền đạt ý nghĩa của hình ảnh.&nbsp;Văn bản thay thế tốt&nbsp;giúp nhiều người hiểu nội dung hơn.&nbsp;Công nghệ hỗ trợ như&nbsp;trình đọc màn hình&nbsp;sẽ đọc to văn bản thay thế để người dùng có thể nghe và hiểu nội dung hình ảnh (VoiceOver của Macbook).</p>



<figure class="wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio"><div class="wp-block-embed__wrapper">
<iframe title="How To Enable Voiceover Screen Narration on macOS [Tutorial]" width="800" height="450" src="https://www.youtube.com/embed/PW9nd4-4zSM?feature=oembed" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>
</div></figure>



<p id="4328">Những người sử dụng trình đọc màn hình thường bị suy giảm thị lực.&nbsp;Điều này bao gồm những người mù hoàn toàn, nhưng cũng có những người có thị lực kém hoặc suy giảm.</p>



<p id="e6ec">Không viết văn bản thay thế có nghĩa là mọi người bỏ lỡ nội dung cần thiết chỉ vì nó trực quan.&nbsp;Nó có nghĩa là nó không thể truy cập được.</p>



<p>Văn bản thay thế được xác định&nbsp;<strong>từ Webaim</strong>:</p>



<figure class="wp-block-pullquote"><blockquote><p>Nó được đọc bởi trình đọc màn hình thay cho hình ảnh cho phép&nbsp;những người có khuyết tật về thị giác hoặc nhận thức nhất định có thể truy cập được&nbsp;<strong>nội dung</strong>&nbsp;và&nbsp;<strong>chức năng của hình ảnh.</strong><br>Nó được hiển thị thay cho hình ảnh trong trình duyệt nếu tệp hình ảnh không được tải hoặc khi người dùng đã chọn không xem hình ảnh.<br>Nó cung cấp ý nghĩa ngữ nghĩa và mô tả cho hình ảnh mà các công cụ tìm kiếm có thể đọc được hoặc được sử dụng để xác định nội dung của hình ảnh sau này chỉ từ ngữ cảnh trang.</p></blockquote></figure>



<p id="e33d">Có&nbsp;nhiều&nbsp;<a href="https://cliquestudios.com/alt-text/" target="_blank" rel="noreferrer noopener">tài nguyên</a>&nbsp;về cách viết văn bản thay thế nói chung (tôi liệt kê thêm ở cuối phần này), nhưng rất ít tài nguyên cung cấp hướng dẫn về cách viết mô tả cho dữ liệu.</p>



<h2 class="wp-block-heading" id="e8f0">Cách viết cho văn bản thay thế cho dữ liệu trực quan (Biểu đồ)</h2>



<p id="162b">Vì vậy, làm thế nào để bạn viết một cái gì đó ngắn gọn mà truyền đạt toàn bộ ý nghĩa của một hình dung?&nbsp;Bạn có thể không thể. Điều đó không có nghĩa là bạn không nên thử.</p>



<ul class="wp-block-list">
<li>Thêm văn bản thay thế sẽ tốt hơn là không làm gì cả nếu có thông tin có ý nghĩa trong hình ảnh.</li>



<li>Thêm một&nbsp;<a href="https://www.w3.org/WAI/tutorials/images/complex/#long-descriptions" rel="noreferrer noopener" target="_blank">mô tả dài</a>&nbsp;nếu bạn có thể thêm HTML, để truyền đạt ý nghĩa đầy đủ hơn.</li>



<li>Bổ sung một liên kết đến dữ liệu thô, để người đọc tò mò có thể truy cập dữ liệu trong chương trình ưa thích của riêng họ.</li>



<li>Giữ văn bản thay thế của bạn ngắn.&nbsp;Văn bản thay thế được trình đọc màn hình đọc tuyến tính, có nghĩa là mọi người không thể quay lại một từ nếu họ bỏ lỡ điều gì đó.&nbsp;Đối với mục đích SEO, Google sẽ cắt bỏ sau một số lượng ký tự nhất định.</li>
</ul>



<p id="9489">World Wide Web Consortium (W3C), một cộng đồng thiết lập các tiêu chuẩn Web quốc tế, đưa ra&nbsp;<a href="https://www.w3.org/WAI/tutorials/images/complex/#long-descriptions" target="_blank" rel="noreferrer noopener">các hướng dẫn về văn bản thay thế cho các hình ảnh phức tạp</a>, nhưng có thể khó diễn giải cách áp dụng các nguyên tắc này để trực quan hóa dữ liệu.&nbsp;Dưới đây, tôi diễn giải những nguyên tắc này để áp dụng cho biểu đồ và đồ thị.&nbsp;Tham khảo&nbsp;<a href="https://www.w3.org/WAI/tutorials/images/complex/#long-descriptions" target="_blank" rel="noreferrer noopener">hướng dẫn của W3C</a>&nbsp;để biết sắc thái và sự tuân thủ.</p>



<p id="1317">Đây là một công thức đơn giản để viết văn bản thay thế để trực quan hóa dữ liệu:</p>



<p>&#8220;<mark style="background-color:#fcb900" class="has-inline-color"><strong>loại biểu đồ</strong></mark> của <strong><mark style="background-color:#8ed1fc" class="has-inline-color">loại dữ liệu</mark></strong>, là <mark style="background-color:#7bdcb5" class="has-inline-color"><strong>lý do cho việc bao gồm biểu đồ</strong></mark>&#8220;. Bao gồm một <strong><mark style="background-color:#fc9200" class="has-inline-color">liên kết đến nguồn dữ liệu</mark></strong>, đâu đó trong văn bản.</p>



<h3 class="wp-block-heading" id="ad8f">Loại biểu đồ</h3>



<p id="dde3">Sẽ hữu ích cho những người có thị lực kém để biết đó là loại biểu đồ nào và đưa ra ngữ cảnh để hiểu phần còn lại của hình ảnh.</p>



<p id="dde3"><em>Ví dụ: Biểu đồ đường</em></p>



<h3 class="wp-block-heading" id="ce3e">Loại dữ liệu</h3>



<p id="9fb8">Dữ liệu nào được bao gồm trong biểu đồ?&nbsp;Nhãn trục x và y có thể giúp bạn tìm ra điều này.</p>



<p id="9fb8"><em>Ví dụ: số thanh long xuất khẩu được mỗi tháng trong năm qua</em></p>



<h2 class="wp-block-heading" id="a245">Lý do bao gồm biểu đồ</h2>



<p id="f051">Hãy suy nghĩ về&nbsp;<strong>lý do tại sao</strong>&nbsp;bạn bao gồm hình ảnh này.&nbsp;Điều đó cho thấy điều đó có ý nghĩa gì.&nbsp;Mỗi hình ảnh nên có một điểm và bạn nên cho mọi người biết những gì cần tìm.</p>



<p id="f051"><em>Ví dụ: những tháng mùa hè bán nhiều thanh long hơn</em></p>



<h3 class="wp-block-heading" id="f0cd">Liên kết đến dữ liệu hoặc nguồn</h3>



<p id="71fc">Không bao gồm điều này trong văn bản thay thế của bạn, nhưng nó nên được bao gồm ở đâu đó trong văn bản xung quanh.&nbsp;Mọi người có thể nhấp vào liên kết để xem dữ liệu nguồn hoặc tìm hiểu sâu hơn về hình ảnh.&nbsp;Điều này mang lại sự minh bạch về nguồn của bạn và cho phép mọi người khám phá dữ liệu.</p>



<p id="71fc"><em>Ví dụ: Dữ liệu từ&nbsp;</em><a href="https://data.ers.usda.gov/reports.aspx?ID=17850" target="_blank" rel="noreferrer noopener"><em>USDA</em></a></p>



<h2 class="wp-block-heading">Ví dụ văn bản thay thế biểu đồ đơn giản<a href="https://medium.com/@amycesal?source=post_page-----2a218ef43f81--------------------------------"></a></h2>



<figure class="wp-block-image size-full is-resized"><img loading="lazy" decoding="async" src="https://media.huynhhieutravel.com/cac-vu-xa-sung-o-my.webp" alt="" class="wp-image-10027" width="700" height="386" srcset="https://media.huynhhieutravel.com/cac-vu-xa-sung-o-my.webp 1400w, https://media.huynhhieutravel.com/cac-vu-xa-sung-o-my-768x423.webp 768w" sizes="(max-width: 700px) 100vw, 700px" /></figure>



<p>Nếu tôi đăng biểu đồ này từ&nbsp;bài báo <a href="https://www.nytimes.com/interactive/2017/11/06/opinion/how-to-reduce-shootings.html" target="_blank" rel="noreferrer noopener">&#8220;Làm thế nào để giảm thiểu các vụ xả súng&#8221; của&nbsp;<em>New York Times</em></a>&nbsp;trên internet, tôi sẽ bao gồm một liên kết đến bài báo và viết văn bản thay thế này:</p>



<p><strong><mark style="background-color:#fcb900" class="has-inline-color">Biểu đồ thanh ngang</mark></strong> về <strong><mark style="background-color:#8ed1fc" class="has-inline-color">các vụ giết người bằng súng trên 100.000 người</mark></strong>, trong đó <strong><mark style="background-color:#00d084" class="has-inline-color">tỷ lệ giết người của Mỹ cao gấp 6 lần so với Canada và 30 lần so với Úc</mark></strong>.</p>



<h2 class="wp-block-heading">Cách thêm văn bản thay thế</h2>



<h3 class="wp-block-heading">Trong soạn thảo của WordPress</h3>



<p>Trong WordPress, sử dụng tính năng &#8220;Media&#8221; cung cấp một cách nhanh chóng và thuận tiện hơn để thêm chú thích và văn bản thay thế (alt image) cho hình ảnh trong trình chỉnh sửa Gutenberg.</p>



<p>Đây là cách bạn có thể làm điều đó:</p>



<ol class="wp-block-list">
<li><strong>Tải lên hình ảnh</strong>: Nhấp vào nút &#8220;+ Thêm khối&#8221; và chọn khối &#8220;Hình ảnh&#8221;. Sau đó, tải lên hình ảnh bạn muốn sử dụng.</li>



<li><strong>Thêm chú thích</strong>: Sau khi hình ảnh được chèn vào, bạn có thể dễ dàng thêm chú thích bằng cách nhấp vào hình ảnh và nhập văn bản mong muốn. Chú thích cung cấp ngữ cảnh và thông tin bổ sung về hình ảnh.</li>



<li><strong>Đặt văn bản thay thế (alt)</strong>: Để đặt văn bản thay thế, hãy nhấp vào hình ảnh và trong cài đặt khối ở phía bên tay phải, bạn sẽ tìm thấy trường &#8220;Văn bản thay thế&#8221;. Nhập một văn bản thay thế có ý nghĩa và mang tính mô tả cho hình ảnh để những người dùng không thể nhìn thấy hình ảnh có thể truy cập được.</li>
</ol>



<figure class="wp-block-image size-full is-resized"><img loading="lazy" decoding="async" src="https://media.huynhhieutravel.com/vi-du-ve-them-van-ban-thay-the-tren-wordpress.jpg" alt="Ví dụ về thêm văn bản thay thế trên WordPress" class="wp-image-10028" width="640" height="360" srcset="https://media.huynhhieutravel.com/vi-du-ve-them-van-ban-thay-the-tren-wordpress.jpg 1280w, https://media.huynhhieutravel.com/vi-du-ve-them-van-ban-thay-the-tren-wordpress-768x432.jpg 768w" sizes="(max-width: 640px) 100vw, 640px" /><figcaption class="wp-element-caption">Ví dụ về thêm văn bản thay thế trên WordPress</figcaption></figure>



<h3 class="wp-block-heading">Trong mã HTML</h3>



<p>Thêm văn bản thay thế alt=&#8221;&#8221; vào bất kỳ hình ảnh nào có thêm ý nghĩa bên trong thẻ hình ảnh. Thêm một mô tả dài longdesc=&#8221;&#8221; khi có thể.</p>



<h3 class="wp-block-heading">Trên Twitter</h3>



<p>Khi bạn thêm hình ảnh, hãy sử dụng nút thêm mô tả hoặc +alt . Twitter có hướng dẫn đầy đủ .</p>



<h3 class="wp-block-heading">Trên Instagram</h3>



<p>Instagram ẩn chức năng văn bản thay thế nhưng có <a href="https://help.instagram.com/503708446705527" target="_blank" rel="noreferrer noopener">tài liệu về cách thêm văn bản thay thế</a>.</p>



<ul class="wp-block-list">
<li>Chọn một bộ lọc và chỉnh sửa hình ảnh, sau đó chạm vào Tiếp theo .</li>



<li>Nhấn vào Cài đặt nâng cao ở cuối màn hình.</li>



<li>Nhấn vào Viết văn bản thay thế.</li>
</ul>



<h3 class="wp-block-heading">Trong Sản phẩm Microsoft Office</h3>



<p>Microsoft Office có nhiều cách để bạn có thể thêm văn bản thay thế tùy thuộc vào chương trình và phiên bản bạn đang sử dụng. Tuy nhiên, họ có nhiều tài liệu về cách thêm văn bản thay thế .</p>



<h3 class="wp-block-heading">Trên Medium</h3>



<p>Bấm vào hình ảnh trong bài viết. Sử dụng nhãn “Văn bản thay thế” để viết văn bản của bạn.</p>



<p>Bằng cách viết văn bản thay thế hoặc văn bản thay thế hiệu quả và bao gồm văn bản đó khi bạn xuất bản trực quan hóa dữ liệu, bạn cung cấp một cách để những người không thể nhìn thấy hình ảnh hiểu nội dung để họ không bỏ lỡ thông tin quan trọng. Có văn bản thay thế là cần thiết để nội dung trực quan có thể truy cập được.<a href="https://www.nytimes.com/interactive/2017/11/06/opinion/how-to-reduce-shootings.html" target="_blank" rel="noreferrer noopener"></a></p>
', 'Bạn có thể không thể viết văn bản truyền đạt toàn bộ ý nghĩa của biểu đồ. Nhưng, điều đó không có nghĩa là bạn không nên thử. Văn bản thay thế là gì? Văn bản thay thế (đôi khi được gọi là thẻ Alt) là các mô tả bằng văn bản được thêm vào hình [&hellip;]', 10110, 'post', '2023-07-24 10:32:14', '2023-07-24 14:13:48');
